import SwiftUI
import NurayaCore
struct SearchView:View {
    @ObservedObject var state:AppState;@State private var query="";@State private var result:SearchResult?;@State private var busy=false;@State private var semantic=true;@State private var voice=false;@State private var error:String?
    var body:some View {PageContainer(dark:state.settings.dark){Text("Cari ayat & makna").font(.system(size:28,weight:.bold));Text("Ketik nama surah, rujukan seperti 2:255, atau topik yang ingin dipelajari.");HStack{TextField("Cari surah, ayat, atau makna",text:$query).textFieldStyle(.roundedBorder).onSubmit{search()};Button{state.audio.stop();voice=true}label:{AppIcon(name:"microphone").frame(width:48,height:48).accessibilityLabel("Cari dengan suara Indonesia")}};Toggle("Pencarian makna",isOn:$semantic);PrimaryButton(title:"Cari",icon:"search"){search()}.disabled(query.trimmingCharacters(in:.whitespacesAndNewlines).isEmpty || busy);if busy {ProgressView("Mencari rujukan…")};if let error=error{Text(error).foregroundStyle(.red)};if let r=result {if r.approximate{Text("Nama yang mendekati. Periksa rujukan sebelum membuka.").foregroundStyle(.orange)};if r.invalid{Text("Nomor ayat tidak ada pada surah tersebut.")}else if r.verses.isEmpty && r.surahs.isEmpty{Text("Belum ada hasil. Coba nama surah, nomor, atau kata yang lebih singkat.")};ForEach(r.surahs){s in Button{state.open(Reference(s.id,1))}label:{MenuRow(title:s.name,subtitle:"\(s.ayahCount) ayat",icon:"book-open-cover",dark:state.settings.dark)}};ForEach(r.verses){v in Button{state.open(v.reference)}label:{VStack(alignment:.leading,spacing:12){Text(state.content.corpus.surahs[v.surah-1].name+" · "+v.reference.id).font(.headline);Text(v.indonesian).font(.system(size:18)).multilineTextAlignment(.leading);Text("Baca ayat & tafsir").font(.subheadline.bold())}.padding(18).frame(maxWidth:.infinity,alignment:.leading).background(Palette(dark:state.settings.dark).card,in:RoundedRectangle(cornerRadius:20))}}};Text("Hasil berasal dari sumber Nuraya. Pencarian makna mencari rujukan, bukan membuat jawaban agama.").font(.footnote).foregroundStyle(.secondary)}.navigationTitle("Cari ayat").sheet(isPresented:$voice){VoiceSearchSheet(state:state,speech:state.speech,onUse:{query=$0;voice=false;search()})}}
    func search(){let q=query.trimmingCharacters(in:.whitespacesAndNewlines);guard !q.isEmpty else{return};busy=true;error=nil;let useSemantic=semantic;let content=state.content;Task{let r=await Task.detached(priority:.userInitiated){content.search?.find(q,semantic:useSemantic)}.value;if q==query.trimmingCharacters(in:.whitespacesAndNewlines){result=r;if r==nil{error="Indeks pencarian belum tersedia."}};busy=false}}
}
struct VoiceSearchSheet:View {
    @ObservedObject var state:AppState;@ObservedObject var speech:SpeechService;let onUse:(String)->Void
    @State private var allowNetwork=false
    var body:some View {NavigationStack{PageContainer(dark:state.settings.dark){Text("Cari dengan suara Indonesia").font(.title2.bold());Text("Contoh: “Cari surat Yasin”, atau “Al-Baqarah ayat dua ratus lima puluh lima”.");Toggle("Izinkan layanan suara Apple jika model lokal belum tersedia",isOn:$allowNetwork);Text("Jika layanan daring digunakan, suara diproses oleh layanan pengenal Apple. Pilihan lokal digunakan saat didukung perangkat.").font(.footnote).foregroundStyle(.secondary);TextEditor(text:$speech.text).frame(minHeight:120).padding(8).overlay(RoundedRectangle(cornerRadius:12).stroke(Color.nuraya.opacity(0.3)));if let e=speech.error{Text(e).foregroundStyle(.red)};PrimaryButton(title:speech.recording ? "Selesai berbicara":"Mulai dikte",icon:"microphone"){if speech.recording{speech.finish()}else{Task{await speech.start(allowNetwork:allowNetwork)}}};PrimaryButton(title:"Gunakan teks dan cari",icon:"search"){speech.stop();onUse(speech.text)}.disabled(speech.text.isEmpty);Text("Perbaiki transkrip bila ada kata yang salah. Mikrofon ini untuk pencarian, bukan latihan bacaan Arab.").font(.footnote)}.navigationTitle("Pencarian suara")}.onDisappear{speech.stop()}}
}
struct HadithView:View {
    @ObservedObject var state:AppState;@State private var query="";@State private var collection="all";@State private var rows=[HadithEntry]();@State private var total=0;@State private var busy=false;@State private var error:String?
    var body:some View {PageContainer(dark:state.settings.dark){TextField("Cari kata atau Bukhari 1",text:$query).textFieldStyle(.roundedBorder).onSubmit{search()};Picker("Kitab",selection:$collection){Text("Semua").tag("all");Text("Bukhari").tag("bukhari");Text("Muslim").tag("muslim")}.pickerStyle(.segmented);PrimaryButton(title:"Cari hadis",icon:"search"){search()}.disabled(query.isEmpty || busy);if busy{ProgressView()};if let e=error{Text(e).foregroundStyle(.red)};Text("\(total) hasil").font(.headline);ForEach(rows){h in NavigationLink{PageContainer(dark:state.settings.dark){Text(h.title).font(.title2.bold());Text(h.section).font(.headline);if !h.arabic.isEmpty{ArabicText(text:h.arabic,size:state.settings.arabicSize)};Text(h.indonesian.isEmpty ? "Terjemahan Indonesia belum tersedia pada entri sumber ini.":h.indonesian).font(.system(size:19)).textSelection(.enabled);if !h.grades.isEmpty{Text(h.grades).font(.footnote)};Text("Sumber: fawazahmed0/hadith-api. Nomor mengikuti edisi sumber.").font(.footnote);ShareLink(item:h.title+"\n"+h.arabic+"\n"+h.indonesian){Text("Bagikan hadis")}}.navigationTitle("Baca hadis")}label:{MenuRow(title:h.title,subtitle:String(h.indonesian.prefix(180)),icon:"book-alt",dark:state.settings.dark)}};if rows.count<total{Button("Tampilkan berikutnya"){search(more:true)}.disabled(busy)};Text("15.152 entri sumber Bukhari dan Muslim. Kekosongan teks ditandai tanpa menambah teks buatan.").font(.footnote).foregroundStyle(.secondary)}.navigationTitle("Cari Hadis")}
    func search(more:Bool=false){busy=true;error=nil;let q=query,c=collection=="all" ? nil:collection,offset=more ? rows.count:0;let store=HadithStore(content:state.content);Task{do{let r=try await Task.detached{try store.search(q,collection:c,offset:offset)}.value;rows=more ? rows+r.rows:r.rows;total=r.total}catch{self.error=error.localizedDescription};busy=false}}
}
struct LearningView:View {
    @ObservedObject var state:AppState;@State private var tab=0;@State private var level=0;@State private var lesson:Lesson?;@State private var sessionOpen=false;@State private var freePractice=false
    var body:some View {PageContainer(dark:state.settings.dark){Text("Hafalan, tajwid & kuis").font(.system(size:26,weight:.bold));Text("Belajar sebentar, ulangi ketika perlu. Semua level terbuka.");Picker("Bagian",selection:$tab){Text("Belajar").tag(0);Text("Hafalan").tag(1);Text("Latihan").tag(2);Text("Progres").tag(3)}.pickerStyle(.segmented)
        if tab==3 {progress}
        else {if state.settings.learning.session != nil {PrimaryButton(title:"Lanjutkan sesi tersimpan",icon:"play"){sessionOpen=true}};if tab==0 {Picker("Level",selection:$level){Text("Dasar").tag(0);Text("Menengah").tag(1);Text("Lanjutan").tag(2)}.pickerStyle(.segmented)};if tab==1{Button{freePractice=true}label:{MenuRow(title:"Hafalan rentang bebas",subtitle:"Pilih ayat dan atur pengulangan",icon:"arrows-repeat-1",dark:state.settings.dark)}};if tab==2{PrimaryButton(title:"Latihan acak",icon:"graduation-cap"){lesson=state.content.lessons.randomElement()}}
        ForEach(state.content.lessons.filter {tab==0 ? $0.level==level : tab==1 ? $0.kind=="memorize":true}){l in Button{lesson=l}label:{HStack(spacing:16){Text(state.settings.learning.records[l.id]==nil ? "○":"✓").font(.title).frame(width:50,height:50).background(Palette(dark:state.settings.dark).raised,in:Circle());VStack(alignment:.leading,spacing:6){Text(l.title).font(.system(size:20,weight:.semibold));Text(l.summary).font(.system(size:16)).foregroundStyle(.secondary);Text(["Dasar","Menengah","Lanjutan"][l.level]).font(.caption)};Spacer();AppIcon(name:"angle-right")}.padding(18).frame(maxWidth:.infinity,alignment:.leading).background(Palette(dark:state.settings.dark).card,in:RoundedRectangle(cornerRadius:24))}}}
    }.navigationTitle("Belajar").sheet(item:$lesson){l in NavigationStack{PageContainer(dark:state.settings.dark){Text(l.title).font(.title.bold());Text(l.explanation).font(.system(size:19));if let v=state.content.corpus.verse(Reference(l.surah,l.ayah)){ArabicText(text:v.text,size:state.settings.arabicSize,study:state.content.study(v.reference),color:state.settings.tajwid);Button("Dengarkan contoh qari"){state.audio.verses(qari:state.selectedQari,start:v.reference,end:v.reference)}};Text("Rujukan: "+l.sourceTitle).font(.footnote);if let u=URL(string:l.sourceUrl){Link("Buka sumber",destination:u)};PrimaryButton(title:"Mulai latihan",icon:"play"){state.audio.stopReader();state.settings.learning.session=LessonSession(lesson:l,course:state.content.lessons,corpus:state.content.corpus);lesson=nil;Task{try? await Task.sleep(nanoseconds:350_000_000);sessionOpen=true}}}.toolbar{Button("Tutup"){lesson=nil}}}}
    .fullScreenCover(isPresented:$sessionOpen){LessonSessionView(state:state)}
    .sheet(isPresented:$freePractice){AudioRangeSheet(state:state,start:state.settings.lastRead ?? Reference(112,1),onPlay:{a,b,e,p in freePractice=false;Task{try? await Task.sleep(nanoseconds:350_000_000);state.open(a);state.audio.verses(qari:state.selectedQari,start:a,end:b,each:e,passes:p)}})}
    .onDisappear{state.audio.stopReader()}}
    var today:String {let f=DateFormatter();f.locale=Locale(identifier:"en_US_POSIX");f.dateFormat="yyyy-MM-dd";return f.string(from:Date())}
    var progress:some View {VStack(alignment:.leading,spacing:20){Text("\(state.settings.learning.xp) XP").font(.system(size:34,weight:.bold));Text("\(state.settings.learning.records.count) pelajaran telah dicoba").font(.title3);Toggle("Target harian pribadi",isOn:$state.settings.learning.goalEnabled);if state.settings.learning.goalEnabled {Stepper("\(state.settings.learning.goal) pelajaran per hari",value:$state.settings.learning.goal,in:1...3)};Text("Lencana pribadi").font(.title2.bold());if state.settings.learning.badges.isEmpty{Text("Lencana muncul dari kegiatan belajarmu. Tidak ada kompetisi.")};ForEach(state.settings.learning.badges,id:\.self){b in Label(b,systemImage:"checkmark.seal")};Text("Hari aktif: \(state.settings.learning.daily.count)");Text("\(state.settings.learning.streak(today:today)) hari berturut-turut");Text("\(state.settings.learning.reviews?.count ?? 0) ayat pernah dinilai mandiri");Text("XP mencatat aktivitas. Penilaian hafalan mandiri bukan pengukuran suara otomatis.").font(.footnote).foregroundStyle(.secondary)}}
}
struct LessonSessionView:View {
    @ObservedObject var state:AppState;@Environment(\.dismiss) var dismiss
    @State private var selected=[String]();@State private var reveal=false;@State private var finished=false;@State private var earned=0
    var session:LessonSession? {state.settings.learning.session}
    var body:some View {NavigationStack{PageContainer(dark:state.settings.dark){if finished{Text("Latihan selesai").font(.largeTitle.bold());Text("+\(earned) XP").font(.system(size:38,weight:.bold));Text("Terima kasih sudah meluangkan waktu untuk belajar. Kamu boleh melanjutkan kapan saja.");PrimaryButton(title:"Kembali ke belajar"){dismiss()}}
        else if let s=session,let ex=s.current {ProgressView(value:Double(s.step),total:Double(max(1,s.exercises.count+s.retries.count)));Text("\(s.step+1) / \(s.exercises.count+s.retries.count)").font(.caption);Text(ex.prompt).font(.system(size:26,weight:.semibold))
            if let ref=ex.reference,let v=state.content.corpus.verse(ref),ex.kind != .recall || reveal {ArabicText(text:v.text,size:state.settings.arabicSize,study:state.content.study(ref),color:state.settings.tajwid)}
            if ex.kind == .recall {if !reveal{PrimaryButton(title:"Tampilkan ayat untuk memeriksa",icon:"eye"){reveal=true}}else{ForEach(["again","help","fluent"],id:\.self){rating in Button(["again":"Perlu mengulang","help":"Masih dibantu","fluent":"Lancar menurut saya"][rating]!){selected=[rating]}.frame(maxWidth:.infinity,minHeight:56).background(selected==[rating] ? Palette(dark:state.settings.dark).raised:Palette(dark:state.settings.dark).card,in:RoundedRectangle(cornerRadius:18))}.disabled(s.checked)}}
            else {if ex.kind == .match,selected.count<ex.left.count {Text("Pasangkan: "+ex.left[selected.count].text).font(.title3.bold())};ForEach(ex.options){option in Button{if ex.kind == .choice{selected=[option.id]}else if let i=selected.firstIndex(of:option.id){selected.remove(at:i)}else{selected.append(option.id)}}label:{HStack{if ex.arabic{ArabicText(text:option.text,size:27)}else{Text(option.text).font(.system(size:19)).multilineTextAlignment(.leading)};if let i=selected.firstIndex(of:option.id){Text(ex.kind == .choice ? "✓":String(i+1)).font(.headline)}}.padding(18).frame(maxWidth:.infinity,minHeight:60,alignment:.leading).background(selected.contains(option.id) ? Palette(dark:state.settings.dark).raised:Palette(dark:state.settings.dark).card,in:RoundedRectangle(cornerRadius:18))}.disabled(s.checked)}}
            if s.checked {Text(s.answers[s.step].correct ? (ex.scored ? "Benar":"Penilaianmu tersimpan"):"Mari periksa lagi").font(.title2.bold());Text(ex.explanation).font(.system(size:19));PrimaryButton(title:"Lanjutkan",icon:"arrow-right"){advance()}}else {PrimaryButton(title:"Periksa"){var session=s;session.submit(selected);state.settings.learning.session=session}.disabled(!answerReady(ex))}
        }else {Text("Sesi belum dipilih.");Button("Kembali"){dismiss()}}
    }.navigationTitle("Latihan Nuraya").navigationBarTitleDisplayMode(.inline).toolbar{ToolbarItem(placement:.navigationBarLeading){Button("Simpan & keluar"){dismiss()}}}}}
    func answerReady(_ ex:Exercise)->Bool {switch ex.kind{case .choice,.recall:return selected.count==1 && (ex.kind != .recall || reveal);case .match:return selected.count==ex.expected.count;case .order:return selected.count==ex.expected.count}}
    func advance(){guard var s=session else{return};s.next();selected=[];reveal=false;if s.complete {let old=state.settings.learning.xp;let f=DateFormatter();f.dateFormat="yyyy-MM-dd";state.settings.learning.finish(s,date:f.string(from:Date()));earned=state.settings.learning.xp-old;finished=true}else{state.settings.learning.session=s}}
}
